export interface Carousel {
    image?: WAMediaUpload;
    video?: WAMediaUpload;
    product?: WASendableProduct;
    title?: string;
    caption?: string;
    footer?: string;
    buttons?: proto.Message.InteractiveMessage.NativeFlowMessage.NativeFlowButton[];
}
type Buttonable = {
    /** add buttons to the message */
    buttons?: proto.Message.ButtonsMessage.IButton[];
    /** force old buttonsMessage format instead of native flow quick replies */
    useLegacyButtons?: boolean;
};
type Templatable = {
    /** add buttons to the message (conflicts with normal buttons) */
    templateButtons?: proto.IHydratedTemplateButton[];
    footer?: string;
};
type Interactiveable = {
    /** add buttons to the message (conflicts with normal buttons) */
    interactiveButtons?: proto.Message.InteractiveMessage.NativeFlowMessage.NativeFlowButton[];
    title?: string;
    subtitle?: string;
    media?: boolean;
};
type Shopable = {
    shop?: proto.Message.InteractiveMessage.ShopMessage.Surface;
    id?: string;
    title?: string;
    subtitle?: string;
    media?: boolean;
};
type Collectionable = {
    collection?: {
        bizJid?: string;
        id?: string;
        version?: number;
    };
    title?: string;
    subtitle?: string;
    media?: boolean;
};
type Cardsable = {
    cards?: Carousel[];
    title?: string;
    subtitle?: string;
};

type Listable = {
    /** Sections of the List */
    sections?: proto.Message.ListMessage.ISection[];
    /** Title of a List Message only */
    title?: string;
    /** Text of the button on the list (required) */
    buttonText?: string;
    /** force old listMessage format instead of native flow single select */
    useLegacyList?: boolean;
};
